/// <summary>
/// Extends RunBaseBatch
/// </summary>
class KCS_KBVSetBPStatus extends RunBaseBatch
{
    // Packed
    TransDate                       transDate;
    CustAccount                     custAccount;

    SysQueryRun                     queryrun;

    DialogField                     dlgtransDate;
    Object                          callerFormDataSource;
    SysQueryRun                     chooseLines;
    Counter                         numberOfRecords;

    boolean                         showQueryForm;
    boolean                         showDialog;

    KCS_KBVStatus                   kcs_KBVStatus;
    DialogField                     dialogKBVStatus;

    SmmQuotationReasonId            smmQuotationReasonId;
    DialogField                     dialogReasonId;

    DialogRunbase                   dialogRunbase;

    KCS_KBVBuildingProjectId        kcs_KBVBuildingProjectId;
    KCS_KBVBuildingProjectTable     kcs_KBVBuildingProjectTable;
    #define.CurrentVersion(2)
    #define.Version1(2)
    #localmacro.CurrentList
        kcs_KBVStatus,
        smmQuotationReasonId
    #endmacro

}

