/// <summary>
/// calerFormDataSource method
/// </summary>
/// <param name = "_callerFormDataSource">FormDataSource</param>
/// <returns>FormDataSource</returns>
FormDataSource callerFormDataSource(FormDataSource _callerFormDataSource = callerFormDataSource)
{
    callerFormDataSource = _callerFormDataSource;

    return callerFormDataSource;
}

public Object dialog()
{
    DialogRunbase   dialog;
    DialogGroup     dialogGroup;

    dialog = super();

    dialogGroup = dialog.addGroup();
    dialogGroup.caption("@NDX:NXABuildingProjectStatus");
    dialogKBVStatus  = dialog.addFieldValue(enumStr(KCS_KBVStatus), kcs_KBVStatus);
    dialogReasonId   = dialog.addFieldValue(extendedtypestr(SmmQuotationReasonId), smmQuotationReasonId);

    return dialog;
}

public boolean getFromDialog()
{
    boolean ret;

    ret = super();

    kcs_KBVStatus           = dialogKBVStatus.value();
    SmmQuotationReasonId    = dialogReasonId.value();

    return ret;
}

/// <summary>
/// initQuery method
/// </summary>
void initQuery()
{
    Query                               query;
    QueryBuildDataSource                qbds;
    QueryBuildRange                     queryBuildRange;

    query = queryRun.query();

    qbds = SysQuery::findOrCreateDataSource(query, tablenum(KCS_KBVBuildingProjectTable));
    queryBuildRange = query.dataSourceTable(tablenum(KCS_KBVBuildingProjectTable)).findRange(fieldnum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectId));

    if (queryBuildRange)
    {
        queryBuildRange.value(queryValue(this.parmkcs_KBVBuildingProjectId()));
    }
}

/// <summary>
/// number of Records counter method
/// </summary>
/// <param name = "_numberOfRecords">Counter</param>
/// <returns>Counter</returns>
Counter numberOfRecords(Counter _numberOfRecords = numberOfRecords)
{
    numberOfRecords = _numberOfRecords;

    return numberOfRecords;
}

/// <summary>
/// parm method for KCS_KBVBuildingProjectId
/// </summary>
/// <param name = "_kcs_KBVBuildingProjectId">KCS_KBVBuildingProjectId</param>
/// <returns>KCS_KBVBuildingProjectId</returns>
public KCS_KBVBuildingProjectId parmkcs_KBVBuildingProjectId(KCS_KBVBuildingProjectId _kcs_KBVBuildingProjectId = kcs_KBVBuildingProjectId)
{
    kcs_KBVBuildingProjectId = _kcs_KBVBuildingProjectId;

    return kcs_KBVBuildingProjectId;
}

/// <summary>
/// parm method for KCS_KBVBuildingProjectTable
/// </summary>
/// <param name = "_kcs_KBVBuildingProjectTable">KCS_KBVBuildingProjectTable</param>
/// <returns>KCS_KBVBuildingProjectTable</returns>
public KCS_KBVBuildingProjectTable parmKcs_KBVBuildingProjectTable(KCS_KBVBuildingProjectTable _kcs_KBVBuildingProjectTable = kcs_KBVBuildingProjectTable)
{
    kcs_KBVBuildingProjectTable = _kcs_KBVBuildingProjectTable;

    return kcs_KBVBuildingProjectTable;
}

QueryRun queryRun(QueryRun  _queryRun = queryRun)
{
    queryRun = _queryRun;

    return queryRun;
}

void run()
{
    int                         recordsUpdated = 0;
    KCS_KBVBuildingProjectTable myKCS_KBVBuildingProjectTable;

    myKCS_KBVBuildingProjectTable = this.parmKcs_KBVBuildingProjectTable();
    if (myKCS_KBVBuildingProjectTable.RecId)
    {
        myKCS_KBVBuildingProjectTable.selectForUpdate(true);
        myKCS_KBVBuildingProjectTable.smmQuotationReasonId    = smmQuotationReasonId;
        myKCS_KBVBuildingProjectTable.KCS_KBVStatus           = kcs_KBVStatus;

        if(myKCS_KBVBuildingProjectTable.validateWrite())
        {
            ttsbegin;
            myKCS_KBVBuildingProjectTable.write();
            recordsUpdated++;
            ttscommit;
        }
    }

    this.numberOfRecords(recordsUpdated);

    if(recordsUpdated > 0)
    {
        info("@KBV172");
    }
}

public boolean unpack(container packedClass)
{
    Version     version = RunBase::getVersion(packedClass);
    container   queryCon;

    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList,queryCon] = packedClass;
            if (!SysQuery::isPackedOk(queryCon))
            {
                this.initQuery();
            }
            break;
        default:
            return false;
    }

    return true;
}

server static KCS_KBVSetBPStatus construct()
{
    return new KCS_KBVSetBPStatus();
}

static void main(Args args)
{
    Common                      record      = args.record();

    if (!args)
    {
        throw error("@SYS25407");
    }

    if (!record.TableId == tablenum(KCS_KBVBUildingProjectTable))
    {
        throw error("@NDX:NXAPassedWrongRecord");
    }
}

